head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > closePopup]<br/>지정한 ID 의 팝업을 닫습니다.",
    "validation" : [
        "id(선택) 파라미터로 닫을 팝업의 ID 를 설정할 수 있어야 합니다.",
        "id 파라미터를 생략하면 URL 파라미터의 popupID 값을 사용하여 현재 팝업을 닫아야 합니다.",
        "id(선택) 생략 시 기본값 undefined 로 동작해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openPopup_onclick = function () {
    var options = {
        id: "popup_1",
        type: "wframePopup",
        width: "600px",
        height: "350px",
        top: "100px",
        left: "100px",
        popupName: "테스트 팝업",
        modal: false
    };

    $p.openPopup("/sample/common_link/util_createPopup_1.xml", options);

    setTimeout(function () {
        var popupList = $p.getAllPopupList();
        wf_body_bottom.getObj("scwin").setReturnValue("현재 팝업 목록 : " + popupList.length + "개");
        for (var i = 0; i < popupList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("[" + i + "] " + JSON.stringify(popupList[i]));
        }
    }, 1000);
}



scwin.btn_closePopup_onclick = function () {
    var id = par_id.getValue();

    if (id === "omit") {
        wf_body_bottom.getObj("scwin").setReturnValue("id 생략은 팝업 내부에서만 테스트 가능합니다. 팝업 내 닫기 버튼을 사용하세요.");
        return;
    }

    $p.closePopup(id);

    setTimeout(function () {
        var popupList = $p.getAllPopupList();
        var found = false;
        for (var i = 0; i < popupList.length; i++) {
            if (popupList[i].id === "popup_1") {
                found = true;
                break;
            }
        }
        wf_body_bottom.getObj("scwin").setReturnValue("closePopup('" + id + "') 실행 완료, 팝업 존재 : " + (found ? "YES" : "NO"));
    }, 500);
}
